    out = [row[:] for row in grid]

    # Reflect patterns across a divider only into the immediately adjacent
    # compartment, and only when that compartment already contains a pattern
    # of the same color elsewhere in the grid.
    hs = [r for r in range(h) if all(x != 0 for x in grid[r])]
    vs = [c for c in range(w) if all(grid[r][c] != 0 for r in range(h))]

    for d in hs:
        above = next((r for r in range(d-1, -1, -1)
                      if all(x != 0 for x in grid[r])), -1)
        below = next((r for r in range(d+1, h)
                      if all(x != 0 for x in grid[r])), h)
        for r in range(above+1, d):
            rr = 2*d-r
            if d < rr < below:
                for c in range(w):
                    if grid[r][c] and not grid[rr][c]:
                        out[rr][c] = grid[r][c]
        for r in range(d+1, below):
            rr = 2*d-r
            if above < rr < d:
                for c in range(w):
                    if grid[r][c] and not grid[rr][c]:
                        out[rr][c] = grid[r][c]

    for d in vs:
        left = next((c for c in range(d-1, -1, -1)
                     if all(grid[r][c] != 0 for r in range(h))), -1)
        right = next((c for c in range(d+1, w)
                      if all(grid[r][c] != 0 for r in range(h))), w)
        for c in range(left+1, d):
            cc = 2*d-c
            if d < cc < right:
                for r in range(h):
                    if grid[r][c] and not grid[r][cc]:
                        out[r][cc] = grid[r][c]
        for c in range(d+1, right):
            cc = 2*d-c
            if left < cc < d:
                for r in range(h):
                    if grid[r][c] and not grid[r][cc]:
                        out[r][cc] = grid[r][c]
    return out
